const body = $input.first().json.body || $input.first().json || {};
const message = (body.message || 'Rappel Pierre').trim();
const echeance = (body.echeance || 'dans 15 minutes').trim();
const priorite = (body.priorite || 'normale').toLowerCase();

// Détection et calcul du délai d'attente (en secondes)
let waitSeconds = 900; // 15 min par défaut
const lower = echeance.toLowerCase();

if (lower.includes('seconde')) {
  const num = parseInt(lower.match(/\d+/)?.[0] || '30', 10);
  waitSeconds = Math.max(num, 5);
} else if (lower.includes('minute') || lower.includes('min')) {
  const num = parseInt(lower.match(/\d+/)?.[0] || '15', 10);
  waitSeconds = Math.max(num * 60, 10);
} else if (lower.includes('heure') || lower.includes('h')) {
  const num = parseInt(lower.match(/\d+/)?.[0] || '1', 10);
  waitSeconds = num * 3600;
} else if (/^\d{4}-\d{2}-\d{2}/.test(echeance)) {
  const targetTime = new Date(echeance).getTime();
  const diffSec = Math.floor((targetTime - Date.now()) / 1000);
  waitSeconds = diffSec > 5 ? diffSec : 10;
}

return [{
  json: {
    message: message,
    echeance: echeance,
    priorite: priorite,
    waitSeconds: waitSeconds,
    scheduled_at: new Date().toISOString()
  }
}];

